/**
 * Root 驱动多文件写盘（emitDerivedFromRoot + 侧车段工具）。
 * 自 interface-derivation.ts 机械拆出。
 *
 * 不变量：
 * - 写出的侧车必须是**合法 ESM**——同一导出名不得出现两段（拼装后自检
 *   导出名唯一性：Babel 不报 duplicate export，测不出来）。
 * - 同一 (目标文件, 目标导出) 的段是**各 root 的并集**（最宽者），且与
 *   命令顺序无关（跨 root 合并时标签取并集并排序）。
 * - 源里已不存在的导出，其 `@generated` 段必须被删掉（否则侧车里留下运行
 *   时不存在的导出，并永久占住那个名字）。
 */
import { existsSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { basename, dirname, relative, resolve } from "node:path";
import {
  constraintToEntryAbs,
  execNudoModule,
  isNodeModulesPath,
  isNudoConstraint,
  localNamedExports,
  parseSource,
  refineDiagCount,
  sidecarPathOf,
  takeRefineDiagsSince,
  type NudoConstraint,
} from "@nudojs/core";
import { DIAG } from "@nudojs/core/internal";

import { unifiedDiff } from "./case-emitter.ts";
import { sanitizeLineCommentText } from "./line-comment.ts";
import {
  deriveFromRoot,
  widestConstraint,
  type ConstraintEntry,
} from "./interface-derivation-derive.ts";
import type { DerivedExport } from "./interface-derivation-project.ts";
import { formatDerivedSection } from "./interface-derivation-rewrite.ts";
import { defaultLoadModule, type LoadModule } from "../load-module.ts";
import { findProjectConfig, interfaceConfig, matchesEmitAllowlist } from "../evaluator/config.ts";

// ---------------------------------------------------------------------------
// Root 驱动多文件写盘（§7.3：emit 永远 root 驱动；下游随根 emit 一并更新）
// ---------------------------------------------------------------------------

export type EmitDerivedResult = {
  /** 被写/将写的下游侧车（绝对路径） */
  sidecars: Array<{
    file: string;
    sidecarPath: string;
    fn: string;
    written: boolean;
    /** 本分支实际写入该侧车的导出名（段文本有变）——调用方据此拼台账 */
    writtenNames?: string[];
    changed: boolean;
    skipped?: "name-clash" | "not-projectable" | "underivable" | "no-change";
    diff?: string;
    /**
     * BUG-196：本分支为该侧车算出的**最终文本**（逐字节等于真写盘的结果）。
     *
     * 同一个侧车同一段只能有**一个写者**：调用方自己写盘时（`skipWrite`）
     * 用它决定落盘内容 ⇒ 写盘与比对（`--dry-run` 预览 / `--exit-on-diff`）
     * **同源**，不会出现「预览里有、盘上没有」的差异。
     */
    finalContent?: string;
    issues: Array<{ code: string; severity: "error" | "warning" | "info"; message: string }>;
  }>;
  hasRoot: boolean;
  roots: string[];
  /** 根在别处 / 无契约根且无已存在生成段 → info */
  entryOnly?: boolean;
  /** 整体失败（如模块图 fail-closed）：无 sidecar 可写时的顶层诊断 */
  issues?: Array<{ code: string; severity: "error" | "warning" | "info"; message: string }>;
};

const DERIVED_HEADER =
  "// @generated by nudo — do not edit; regenerate with `nudo contract --emit`";

/**
 * Root 驱动 emit：对 rootFile 的手写契约根做下行推导，把闭包内被点名的
 * 下游导出写入**各自**的 `*.nudo.js`（§7.3 / §11 Phase 2 验收：
 * `--emit src/lib.js --fn add2` 只写 add.nudo.js 的 add2）。
 *
 * 手写绑定永不覆盖；round-trip 自检失败不写垃圾。
 */
/**
 * 侧车顶层标识符（import local / 顶层声明 / export 名）。
 * 新生成段据此避让，避免同文件重复 `const x` / 重复 import 绑定。
 */
function collectTopLevelNames(src: string): Set<string> {
  const names = new Set<string>();
  if (src.trim() === "") return names;
  let ast: ReturnType<typeof parseSource>;
  try {
    ast = parseSource(src);
  } catch {
    return names;
  }
  const addDecl = (d: ReturnType<typeof parseSource>["program"]["body"][number]): void => {
    if (d.type === "VariableDeclaration") {
      for (const decl of d.declarations) {
        if (decl.id.type === "Identifier") names.add(decl.id.name);
      }
    } else if (d.type === "FunctionDeclaration" || d.type === "ClassDeclaration") {
      if (d.id) names.add(d.id.name);
    }
  };
  for (const stmt of ast.program.body) {
    if (stmt.type === "ImportDeclaration") {
      for (const s of stmt.specifiers) names.add(s.local.name);
      continue;
    }
    if (stmt.type === "ExportNamedDeclaration") {
      if (stmt.declaration) addDecl(stmt.declaration);
      for (const spec of stmt.specifiers) {
        names.add(
          spec.exported.type === "Identifier" ? spec.exported.name : spec.exported.value,
        );
      }
      continue;
    }
    addDecl(stmt);
  }
  return names;
}

function sidecarAssembles(text: string, fromFile: string, loadModule: LoadModule): boolean {
  // 重复导出名：Babel **不报** duplicate export（侧车执行把 export 摘成对象
  // 字面量，重复键被静默吞掉）——拼装阶段必须自己查，否则侧车成非法 ESM
  // （`SyntaxError: Duplicate export of 'x'`，整份侧车装载失败）。
  if (duplicateExportNames(text).length > 0) return false;
  try {
    parseSource(text);
    execNudoModule(text, { loadModule, fromFile });
    return true;
  } catch {
    return false;
  }
}

/** 侧车里的重复导出名（升序） */
function duplicateExportNames(src: string): string[] {
  if (src.trim() === "") return [];
  let ast: ReturnType<typeof parseSource>;
  try {
    ast = parseSource(src);
  } catch {
    return [];
  }
  const seen = new Set<string>();
  const dup = new Set<string>();
  const add = (n: string): void => {
    if (seen.has(n)) dup.add(n);
    else seen.add(n);
  };
  for (const stmt of ast.program.body) {
    if (stmt.type === "ExportNamedDeclaration") {
      const d = stmt.declaration;
      if (d) {
        if (d.type === "VariableDeclaration") {
          for (const decl of d.declarations) {
            if (decl.id.type === "Identifier") add(decl.id.name);
          }
        } else if ((d.type === "FunctionDeclaration" || d.type === "ClassDeclaration") && d.id) {
          add(d.id.name);
        }
      }
      if (!stmt.source) {
        for (const spec of stmt.specifiers) {
          add(spec.exported.type === "Identifier" ? spec.exported.name : spec.exported.value);
        }
      }
    } else if (stmt.type === "ExportDefaultDeclaration") {
      add("default");
    }
  }
  return [...dup].sort();
}

export function emitDerivedFromRoot(
  rootFile: string,
  opts: {
    fnNames?: string[];
    mode: "add" | "update";
    dryRun?: boolean;
    loadModule?: LoadModule;
    autoBind?: boolean;
    /** 只刷新目标侧车里已存在的 @generated 段（不发明新下游契约） */
    refreshExistingOnly?: boolean;
    /**
     * BUG-196：**调用方给定的基底内容**（按侧车路径）——调用方自己决定该侧车
     * 的最终形态（如 CLI：直写分支的产物）⇒ 派生分支据此算出最终文本，
     * 写盘与比对同源。回调返回 `undefined` ⇒ 该侧车照旧从磁盘读。
     */
    baseContent?: (sidecarPath: string) => string | undefined;
    /**
     * BUG-196：这些侧车由**调用方**写盘（派生分支只算不写）⇒ 同一侧车同一段
     * 只有一个写者（直写分支/派生分支不再各写各的）。
     */
    skipWrite?: string[];
    /**
     * BUG-196：**直写分支负责**的导出名——这些名字的段正文归直写分支，派生
     * 分支**不整段覆盖**，只把 `// derived-from:` 标签行并进去（标签行丢失
     * 是旧实现最大的坑：直写分支随后整段重写 ⇒ 标签被抹掉）。
     */
    directSections?: Set<string>;
  },
): EmitDerivedResult {
  const abs = resolve(rootFile);
  const derive = deriveFromRoot(abs, {
    ...(opts.loadModule ? { loadModule: opts.loadModule } : {}),
    ...(opts.autoBind !== undefined ? { autoBind: opts.autoBind } : {}),
    ...(opts.fnNames && opts.fnNames.length > 0 ? { fnNames: opts.fnNames } : {}),
  });

  if (!derive.hasRoot) {
    return { sidecars: [], hasRoot: false, roots: [], entryOnly: true };
  }

  // 模块图 fail-closed（BUG-017 同径）：不带空 import 表推导，emit 也不写垃圾
  if (derive.graphError) {
    return {
      sidecars: [],
      hasRoot: true,
      roots: derive.roots,
      issues: [
        {
          code: DIAG.moduleMissing,
          severity: "error",
          message: `derivation aborted: ${derive.graphError}`,
        },
      ],
    };
  }

  // package.json#nudo.contract.emit 白名单（Phase 3 §7.3）
  const proj = findProjectConfig(dirname(abs));
  const allow = interfaceConfig(proj?.config).emit;
  const projectDir = proj?.projectDir;

  const rootSidecarDir = dirname(sidecarPathOf(abs));
  const wanted =
    opts.fnNames && opts.fnNames.length > 0 ? new Set(opts.fnNames) : undefined;

  const result: EmitDerivedResult = {
    sidecars: [],
    hasRoot: true,
    roots: derive.roots,
  };

  // 按目标侧车分组（同文件多导出一次读写）
  const bySidecar = new Map<string, typeof derive.derived>();
  for (const row of derive.derived) {
    if (wanted && !wanted.has(row.fn)) continue;
    if (!matchesEmitAllowlist(row.file, projectDir, allow)) continue;
    const sp = sidecarPathOf(row.file);
    if (isNodeModulesPath(sp)) continue;
    const list = bySidecar.get(sp) ?? [];
    list.push(row);
    bySidecar.set(sp, list);
  }

  // BUG-196：调用方写盘的侧车（CLI 的根侧车）⇒ 本分支只算不写
  const skipWritePaths = new Set((opts.skipWrite ?? []).map((p) => resolve(p)));

  for (const [sidecarPath, rows0] of bySidecar) {
    const targetFile = rows0[0]!.file;
    const targetSidecarDir = dirname(sidecarPath);
    // BUG-196：基底内容可由调用方注入（= 该侧车真写盘时的基底）⇒ 本分支
    // 算出的最终文本与调用方写盘的内容**同源**。
    const injectedBase = opts.baseContent?.(sidecarPath);
    const prevSrc =
      injectedBase !== undefined
        ? injectedBase
        : existsSync(sidecarPath)
          ? readFileSync(sidecarPath, "utf-8")
          : "";

    // refreshExistingOnly：只碰已有生成段的导出，不发明新契约
    const rows = opts.refreshExistingOnly
      ? rows0.filter((r) => findGeneratedSectionText(prevSrc, r.fn) !== undefined)
      : rows0;
    if (rows.length === 0) continue;

    // 手写绑定名（顶层声明 − 生成段）
    const handwritten = handwrittenNames(prevSrc);
    const loadModule = opts.loadModule ?? defaultLoadModule;
    // 目标源里当前**活着**的导出名（空集 = 扫描失败 → 不做死段判定）
    const live = liveExportNames(targetFile);

    // update：剥离「本批可能重写」的生成段后收集残留顶层名；format 失败的
    // 段会保留旧文，其名字在失败时回填 taken（避免新段抢占）。
    const batchFns = new Set(
      rows.filter((r) => !r.underivable && !handwritten.has(r.fn)).map((r) => r.fn),
    );
    const baseForNames =
      opts.mode === "update" ? stripGeneratedFor(prevSrc, batchFns) : prevSrc;
    const taken = collectTopLevelNames(baseForNames);

    const accepted: Array<{ fn: string; text: string; prevText?: string }> = [];
    const issues: EmitDerivedResult["sidecars"][number]["issues"] = [];
    const written: string[] = [];
    let anySkip: EmitDerivedResult["sidecars"][number]["skipped"];

    const acceptedFnsSeen = new Set<string>();
    for (const row of rows) {
      if (handwritten.has(row.fn)) {
        issues.push({
          code: DIAG.interfaceNameClash,
          severity: "error",
          message: `sidecar already has a handwritten binding '${row.fn}' (${relative(process.cwd(), sidecarPath) || sidecarPath}); handwritten wins — skipping emit`,
        });
        anySkip = "name-clash";
        continue;
      }
      // 目标源里已不存在该导出 → 不给它写契约（否则侧车里留下运行时不存在的
      // 导出，并永久占住那个名字；用户为同名新函数手写侧车 ⇒ 侧车语法错）
      if (isDeadName(row.fn, live)) {
        issues.push({
          code: DIAG.interfaceNotProjectable,
          severity: "info",
          message: `${row.fn}: no longer exported by ${relative(process.cwd(), targetFile) || targetFile} — dropping its derived section`,
        });
        anySkip = "not-projectable";
        continue;
      }
      // 同名两段（同一导出名被写进同一侧车两次）⇒ 非法 ESM：拒绝第二段
      if (acceptedFnsSeen.has(row.fn)) {
        issues.push({
          code: DIAG.interfaceNotProjectable,
          severity: "error",
          message: `duplicate derived section for '${row.fn}' in ${relative(process.cwd(), sidecarPath) || sidecarPath} — refusing to write (duplicate export)`,
        });
        anySkip = "not-projectable";
        continue;
      }
      if (row.underivable) {
        issues.push({
          code: DIAG.interfaceUnderivable,
          severity: "info",
          message: `${row.fn}: contract underivable from ${row.derivedFrom} (opaque / truncated / no evidence)`,
        });
        anySkip = "underivable";
        continue;
      }
      const prevSection = findGeneratedSectionText(prevSrc, row.fn);
      const body = formatDerivedSection(row, {
        rootSidecarDir,
        targetSidecarDir,
        takenNames: taken,
      });
      if (!body) {
        anySkip = "not-projectable";
        // 旧段将原样保留 → 名字继续占用
        if (prevSection !== undefined) {
          for (const n of collectTopLevelNames(prevSection)) taken.add(n);
        }
        continue;
      }
      for (const n of body.usedNames) taken.add(n);
      const srcRel = relative(targetSidecarDir, targetFile) || basename(targetFile);
      const buildSection = (labels: string[]): string =>
        [
          DERIVED_HEADER,
          `// source: ${sanitizeLineCommentText(`${srcRel}:${row.fn}`)}`,
          `// derived-from: ${sanitizeLineCommentText(labels.join(", "))}`,
          body.text,
          "",
        ].join("\n");

      // 跨 root 合并（Bug 525）：既有段来自**别的** root 时，按名覆盖会让快照
      // 只覆盖部分调用点（且**顺序相关**——谁后写谁赢）。改为与既有段求并集：
      // 并集取**最宽**者（x>5 ⊆ x>1 → 并集 = x>1），标签取并集（排序 → 顺序无关）。
      const rowLabels = splitLabels(row.derivedFrom);
      const prevLabels = prevSection !== undefined ? derivedFromLabels(prevSection) : [];
      // BUG-196：段归**直写分支**所有（调用方点名）⇒ 派生分支**不整段覆盖**，
      // 只把 `// derived-from:` 标签行并进去：直写分支的正文优先（同一段只
      // 有一个写者），标签行不再被随后那次整段重写抹掉。
      const directOwned =
        opts.directSections !== undefined && opts.directSections.has(row.fn);
      const needsMerge =
        prevSection !== undefined && prevLabels.length > 0 && !sameLabelSet(prevLabels, rowLabels);
      let section: string;
      if (directOwned && prevSection !== undefined) {
        section = withDerivedFromLabelLine(
          prevSection,
          prevLabels.length > 0 ? mergeLabels(prevLabels, rowLabels) : rowLabels,
        );
      } else if (needsMerge) {
        const mergedLabels = mergeLabels(prevLabels, rowLabels);
        const decision = mergeDecision(row, prevSection!, sidecarPath, loadModule);
        if (decision === undefined) {
          // 并集不可比较 → 既有段原样保留（**禁止**拿任一侧窄化另一侧）
          anySkip = "not-projectable";
          issues.push({
            code: DIAG.interfaceNotProjectable,
            severity: "error",
            message: `${row.fn}: cannot merge the existing derived section with the one from ${row.derivedFrom} (incomparable domains) — keeping the existing section`,
          });
          for (const n of collectTopLevelNames(prevSection!)) taken.add(n);
          continue;
        }
        section =
          decision === "prev"
            ? withDerivedFromLabels(prevSection!, mergedLabels)
            : buildSection(mergedLabels);
      } else {
        section = buildSection(rowLabels);
      }

      // round-trip：整段（含 import）必须可执行——fromFile 用目标侧车路径，
      // 相对 spec（./std.nudo.js）按该目录解析
      if (!derivedRoundTrips(section, row.fn, sidecarPath, loadModule)) {
        anySkip = "not-projectable";
        if (prevSection !== undefined) {
          for (const n of collectTopLevelNames(prevSection)) taken.add(n);
        }
        continue;
      }

      if (opts.mode === "add" && prevSection !== undefined) {
        anySkip = "no-change";
        for (const n of collectTopLevelNames(prevSection)) taken.add(n);
        continue;
      }
      const norm = normalizeSectionText(section);
      if (prevSection !== undefined && normalizeSectionText(prevSection) === norm) {
        anySkip = "no-change";
        acceptedFnsSeen.add(row.fn);
        accepted.push({ fn: row.fn, text: prevSection, prevText: prevSection });
        for (const n of collectTopLevelNames(prevSection)) taken.add(n);
        continue;
      }
      written.push(row.fn);
      acceptedFnsSeen.add(row.fn);
      accepted.push({ fn: row.fn, text: section, ...(prevSection !== undefined ? { prevText: prevSection } : {}) });
    }

    // 组装：update 只剥离**已接受**的生成段；underivable/not-projectable/
    // name-clash 的既有段原样保留（证据退化不静默删契约）。
    // accepted 为空时必须原样保留——否则 stripped=prev + preserved 会叠层。
    // 死段（源里已不存在的导出）先剥掉（Bug 542）：否则侧车里留下运行时不
    // 存在的导出，并永久占住那个名字。
    const cleanedPrev = stripDeadSections(prevSrc, live);
    let finalContent: string;
    if (accepted.length === 0) {
      finalContent = cleanedPrev;
    } else if (opts.mode === "add") {
      finalContent = joinSectionTexts(cleanedPrev, accepted.map((a) => a.text));
    } else {
      const acceptedFns = new Set(accepted.map((a) => a.fn));
      const stripped = stripGeneratedFor(cleanedPrev, acceptedFns);
      // 保留段（未被本次重写的 @generated 段）**留在原位**——stripped 只剥了
      // 「本次接受」的段，保留段仍在其中；再拼一遍会让同一段出现两次
      // （侧车成非法 ESM：同一导出名两段 → Duplicate export）。
      finalContent = joinSectionTexts(stripped, accepted.map((a) => a.text));
    }

    // 整文件 round-trip：同侧车多段拼装后仍必须是合法可执行模块
    // （单段自检挡不住 duplicate import / const 重定义）
    if (finalContent.trim() !== "" && !sidecarAssembles(finalContent, sidecarPath, loadModule)) {
      issues.push({
        code: DIAG.interfaceNotProjectable,
        severity: "error",
        message: `assembled sidecar failed round-trip (${relative(process.cwd(), sidecarPath) || sidecarPath}); refusing to write`,
      });
      anySkip = "not-projectable";
      result.sidecars.push({
        file: targetFile,
        sidecarPath,
        fn: rows.map((r) => r.fn).join(","),
        written: false,
        changed: false,
        ...(anySkip ? { skipped: anySkip } : {}),
        issues,
      });
      continue;
    }

    const changed = finalContent !== prevSrc;
    const diff = changed
      ? unifiedDiff(prevSrc, finalContent, relative(process.cwd(), sidecarPath) || sidecarPath)
      : undefined;

    // BUG-196：调用方写盘的侧车 ⇒ 本分支**只算不写**（唯一写者）
    if (changed && !opts.dryRun && !skipWritePaths.has(resolve(sidecarPath))) {
      const tmp = `${sidecarPath}.tmp-${process.pid}-${Math.random().toString(16).slice(2, 10)}`;
      try {
        writeFileSync(tmp, finalContent, "utf-8");
        renameSync(tmp, sidecarPath);
      } catch (e) {
        try {
          if (existsSync(tmp)) unlinkSync(tmp);
        } catch {
          /* best-effort */
        }
        throw e;
      }
    }

    result.sidecars.push({
      file: targetFile,
      sidecarPath,
      fn: rows.map((r) => r.fn).join(","),
      written: written.length > 0 && changed,
      writtenNames: written,
      changed,
      ...(anySkip ? { skipped: anySkip } : {}),
      ...(diff !== undefined ? { diff } : {}),
      // BUG-196：最终文本随结果回传 ⇒ 调用方（唯一写者）落盘时逐字节一致
      finalContent,
      issues,
    });
  }

  return result;
}

// --- 侧车段工具（与 interface-emitter 同口径，独立实现避免循环依赖）---

/**
 * 单个生成段：`names` = 身份（导出名），`bindings` = 段在模块作用域引入的
 * 绑定标识符（别名段 `_nudo_<n>`，直发段与身份同名）。
 */
type RawSection = { names: string[]; bindings: string[]; start: number; end: number; text: string };

/**
 * nudo 自己的**生成段标记行**：注释的**首个记号**是 `@generated`，且标注文本
 * 点名 nudo（`@generated by nudo — do not edit; regenerate with …`）。
 *
 * Bug 440：旧判定是裸子串 `/@generated/` ⇒ 侧车里任何**散文提及**
 * （`// 手写契约：这里提到了 @generated 这个词`）都算生成标记 ⇒ 手写段的
 * L1 义务整体消失 + emit 侧整段覆盖手写契约（Bug 443）。
 * 口径与 core `scan-named-exports.ts` 的 `isGeneratedMarkerLine` 一致。
 */
function isGeneratedMarkerLine(line: string): boolean {
  const t = line.trim();
  let rest: string;
  if (t.startsWith("//")) rest = t.slice(2);
  else if (t.startsWith("/*")) rest = t.slice(2);
  else if (t.startsWith("*")) rest = t.slice(1);
  else return false;
  rest = rest.trim();
  if (!/^@generated\b/.test(rest)) return false;
  return /\bby\s+nudo\b/.test(rest);
}

type AstNode = { type?: string; name?: string; computed?: boolean; [k: string]: unknown };

const SKIPPED_NODE_KEYS = new Set([
  "type",
  "name",
  "start",
  "end",
  "loc",
  "range",
  "extra",
  "leadingComments",
  "trailingComments",
  "innerComments",
  "comments",
  "errors",
]);

/** 节点子树里出现的标识符名（非计算属性键只是键名，不算「引用」） */
function collectIdentNames(node: unknown, out: Set<string>): void {
  if (node === null || typeof node !== "object") return;
  if (Array.isArray(node)) {
    for (const n of node) collectIdentNames(n, out);
    return;
  }
  const obj = node as AstNode;
  if (obj.type === "Identifier" && typeof obj.name === "string") out.add(obj.name);
  const t = obj.type;
  const skipKey =
    obj.computed === false &&
    (t === "ObjectProperty" ||
      t === "ObjectMethod" ||
      t === "ClassMethod" ||
      t === "ClassProperty" ||
      t === "ClassPrivateProperty" ||
      t === "ClassAccessorProperty" ||
      t === "MemberExpression");
  for (const key of Object.keys(obj)) {
    if (SKIPPED_NODE_KEYS.has(key)) continue;
    if (skipKey && key === "key") continue;
    if (skipKey && key === "property") continue;
    collectIdentNames(obj[key], out);
  }
}

/**
 * export 所属**生成段**的「段内链」：export 自身 + 紧邻的 import +
 * **被 export 引用**的 const（组合式 §5.3 的 prelude const、多步 prelude 的
 * 中间量、DESIGN-003 的别名绑定 const）。口径与 core
 * `scan-named-exports.ts` 的 `sectionChainIndices` 一致。
 */
function sectionChainIndices(
  stmts: ReturnType<typeof parseSource>["program"]["body"],
  exportIdx: number,
): Set<number> {
  const chain = new Set<number>([exportIdx]);
  const referenced = new Set<string>();
  collectIdentNames(stmts[exportIdx], referenced);
  for (let j = exportIdx - 1; j >= 0; j--) {
    const prev = stmts[j]!;
    if (prev.type === "ImportDeclaration") {
      chain.add(j);
      continue;
    }
    if (prev.type === "VariableDeclaration") {
      const declared: string[] = [];
      for (const d of prev.declarations) {
        if (d.id.type === "Identifier") declared.push(d.id.name);
      }
      if (!declared.some((n) => referenced.has(n))) break;
      for (const d of prev.declarations) collectIdentNames(d.init, referenced);
      chain.add(j);
      continue;
    }
    break;
  }
  return chain;
}

/**
 * 段头（`@generated` 标记行）是否**拥有**该 export：头之后的第一条顶层语句
 * 必须就是该 export 的段内链的**第一条**（段内链之外夹了语句 ⇒ 头不拥有它）。
 */
function headerOwnsExport(
  stmts: ReturnType<typeof parseSource>["program"]["body"],
  exportIdx: number,
  headerPos: number,
): boolean {
  const chain = sectionChainIndices(stmts, exportIdx);
  let first = exportIdx;
  for (const idx of chain) if (idx < first) first = idx;
  // 头之后的第一条顶层语句
  for (let k = 0; k < stmts.length; k++) {
    const start = stmts[k]!.start;
    if (start == null || start < headerPos) continue;
    return k === first;
  }
  return false;
}

function collectGeneratedSectionsRaw(src: string): RawSection[] {
  if (src.trim() === "") return [];
  let ast: ReturnType<typeof parseSource>;
  try {
    ast = parseSource(src);
  } catch {
    return [];
  }
  const stmts = ast.program.body;
  const out: RawSection[] = [];
  // 从 @generated 注释行起，到其后第一个顶层 export 止——中间允许
  // import / prelude const（组合式 §5.3 形态）/ 别名段的 const（DESIGN-003：
  // `const _nudo_1 = …; export { _nudo_1 as class };` 两句都在段内）。
  for (const headerPos of findGeneratedHeaderOffsets(src)) {
    for (let i = 0; i < stmts.length; i++) {
      const stmt = stmts[i]!;
      if (stmt.type !== "ExportNamedDeclaration" || stmt.source) continue;
      if (stmt.start == null || stmt.end == null || stmt.start < headerPos) continue;
      // Bug 432：段边界收紧——头与 export 之间的语句必须**全在段内链**
      // （import + 被该 export 引用的 const）。夹着用户自己的 const ⇒ 这个头
      // **不拥有**该 export（否则上一段的头落进本段 ⇒ 手写段被判成生成段 ⇒
      // 「手写优先」保护被绕过 ⇒ emit 整段覆盖手写契约）。
      if (!headerOwnsExport(stmts, i, headerPos)) continue;
      const d = stmt.declaration;
      const names: string[] = [];
      const bindings: string[] = [];
      if (d) {
        if (d.type === "VariableDeclaration") {
          for (const decl of d.declarations) {
            if (decl.id.type === "Identifier") {
              names.push(decl.id.name);
              bindings.push(decl.id.name);
            }
          }
        } else if (d.type === "FunctionDeclaration" || d.type === "ClassDeclaration") {
          if (d.id) {
            names.push(d.id.name);
            bindings.push(d.id.name);
          }
        }
      } else {
        // 别名段尾（DESIGN-003）：export 子句无声明——身份=导出名（含 string
        // 名），绑定=specifier local（const 在 header 与子句之间，已入切片）
        for (const spec of stmt.specifiers) {
          if (spec.type !== "ExportSpecifier") continue;
          names.push(
            spec.exported.type === "Identifier" ? spec.exported.name : spec.exported.value,
          );
          if (spec.local.type === "Identifier") bindings.push(spec.local.name);
        }
      }
      if (names.length === 0) continue;
      out.push({
        names,
        bindings,
        start: headerPos,
        end: stmt.end,
        text: src.slice(headerPos, stmt.end),
      });
      break;
    }
  }
  return out;
}

/** 注释行上的 `@generated` 标记字节偏移（段起点）——nudo 自己的标记才算 */
function findGeneratedHeaderOffsets(src: string): number[] {
  const out: number[] = [];
  let pos = 0;
  for (const line of src.split("\n")) {
    if (isGeneratedMarkerLine(line)) out.push(pos);
    pos += line.length + 1;
  }
  return out;
}

function handwrittenNames(src: string): Set<string> {
  if (src.trim() === "") return new Set();
  let ast: ReturnType<typeof parseSource>;
  try {
    ast = parseSource(src);
  } catch {
    return new Set();
  }
  const names = new Set<string>();
  const collect = (stmt: ReturnType<typeof parseSource>["program"]["body"][number]): void => {
    if (stmt.type === "VariableDeclaration") {
      for (const d of stmt.declarations) {
        if (d.id.type === "Identifier") names.add(d.id.name);
      }
    } else if (stmt.type === "FunctionDeclaration" || stmt.type === "ClassDeclaration") {
      if (stmt.id) names.add(stmt.id.name);
    }
  };
  for (const stmt of ast.program.body) {
    if (stmt.type === "ExportNamedDeclaration") {
      if (stmt.declaration) collect(stmt.declaration);
      if (!stmt.source) {
        for (const spec of stmt.specifiers) {
          names.add(
            spec.exported.type === "Identifier" ? spec.exported.name : spec.exported.value,
          );
        }
      }
    } else {
      collect(stmt);
    }
  }
  // 生成段不算手写（DESIGN-003：身份名与别名绑定都扣除——别名段的
  // `const _nudo_1` / 导出面不是手写）
  for (const s of collectGeneratedSectionsRaw(src)) {
    for (const n of s.names) names.delete(n);
    for (const b of s.bindings) names.delete(b);
  }
  return names;
}

function findGeneratedSectionText(src: string, fn: string): string | undefined {
  return collectGeneratedSectionsRaw(src).find((s) => s.names.includes(fn))?.text;
}

function stripSections(src: string, sections: RawSection[]): string {
  if (sections.length === 0) return src;
  const sorted = [...sections].sort((a, b) => a.start - b.start);
  let out = "";
  let pos = 0;
  for (const s of sorted) {
    out += src.slice(pos, s.start);
    pos = Math.max(pos, s.end);
  }
  out += src.slice(pos);
  return out;
}

function stripGeneratedFor(src: string, fns: Set<string>): string {
  return stripSections(
    src,
    collectGeneratedSectionsRaw(src).filter((s) => s.names.some((n) => fns.has(n))),
  );
}

// --- 死段清理（源里已不存在的导出）---

/** 目标源里当前**活着**的导出名（空集 = 扫描失败 → 不判死段） */
function liveExportNames(targetFile: string): Set<string> {
  try {
    return localNamedExports(readFileSync(targetFile, "utf-8"));
  } catch {
    return new Set();
  }
}

/** 名字在源里已不存在（只认普通标识符——`Class.method` 形态不判） */
function isDeadName(name: string, live: Set<string>): boolean {
  if (live.size === 0) return false;
  if (!/^[A-Za-z_$][\w$]*$/.test(name)) return false;
  return !live.has(name);
}

/** 剥掉死段（段里的名字在源里都已不存在） */
function stripDeadSections(src: string, live: Set<string>): string {
  if (live.size === 0) return src;
  const dead = collectGeneratedSectionsRaw(src).filter((s) =>
    s.names.every((n) => isDeadName(n, live)),
  );
  return stripSections(src, dead);
}

// --- 跨 root 合并（标签 / 并集）---

/** 标签串 → 标签数组（`a, b` → ["a","b"]） */
function splitLabels(text: string): string[] {
  return text
    .split(",")
    .map((s) => s.trim())
    .filter((s) => s !== "");
}

/** 段内 `// derived-from:` 的标签集 */
function derivedFromLabels(sectionText: string): string[] {
  const m = /^\s*\/\/\s*derived-from:\s*(.+)$/m.exec(sectionText);
  if (!m) return [];
  return splitLabels(m[1]!);
}

/** 标签并集（排序 → 与写入顺序无关） */
function mergeLabels(a: string[], b: string[]): string[] {
  return [...new Set([...a, ...b])].sort();
}

/** 标签集相等 */
function sameLabelSet(a: string[], b: string[]): boolean {
  if (a.length !== b.length) return false;
  const set = new Set(a);
  return b.every((l) => set.has(l));
}

/** 替换段内的 derived-from 标签行 */
function withDerivedFromLabels(sectionText: string, labels: string[]): string {
  return sectionText.replace(
    /^(\s*\/\/\s*derived-from:).*$/m,
    (_m, p1: string) => `${p1} ${sanitizeLineCommentText(labels.join(", "))}`,
  );
}

/**
 * BUG-196：把 `// derived-from:` 标签行**并进**既有段文本。
 *
 * 段内已有标签行 ⇒ 替换标签内容（调用方已决定合并后的标签集）；
 * 没有 ⇒ **插入**一行：优先插在 `// source:` 行之后（与派生段自身的版式
 * 一致），没有 source 行则插在 `@generated` 标记行之后，都没有则插在
 * 段首。行尾沿用既有段的 CRLF/LF ⇒ 不制造混合行尾。
 */
function withDerivedFromLabelLine(sectionText: string, labels: string[]): string {
  if (derivedFromLabels(sectionText).length > 0) {
    return withDerivedFromLabels(sectionText, labels);
  }
  const eol = sectionText.includes("\r\n") ? "\r\n" : "\n";
  const lines = sectionText.split(/\r?\n/);
  const srcIdx = lines.findIndex((l) => /^\s*\/\/\s*source:/.test(l));
  const genIdx = lines.findIndex((l) => isGeneratedMarkerLine(l));
  const at = srcIdx >= 0 ? srcIdx + 1 : genIdx >= 0 ? genIdx + 1 : 0;
  lines.splice(at, 0, `// derived-from: ${sanitizeLineCommentText(labels.join(", "))}`);
  return lines.join(eol);
}

/** 既有生成段的 fn 约束（参数位 + 返回位） */
function sectionFnConstraint(
  sectionText: string,
  fn: string,
  fromFile: string,
  loadModule: LoadModule,
): { params: Record<string, NudoConstraint>; returns?: NudoConstraint } | undefined {
  try {
    const exports = execNudoModule(sectionText, { loadModule, fromFile });
    const v = exports[fn];
    if (!isNudoConstraint(v)) return undefined;
    const f = (v as { fn?: { params?: Record<string, NudoConstraint>; returns?: NudoConstraint } })
      .fn;
    if (!f || typeof f !== "object") return undefined;
    return {
      params: f.params ?? {},
      ...(f.returns !== undefined ? { returns: f.returns } : {}),
    };
  } catch {
    return undefined;
  }
}

/**
 * 跨 root 合并的取舍：既有段与本行的域求**并集**（取最宽者）。
 * 返回 "prev"（沿用既有段的正文）/ "current"（用本行的正文）；
 * 不可比较 → undefined（调用方保留既有段，**禁止**拿任一侧窄化另一侧）。
 */
function mergeDecision(
  row: DerivedExport,
  prevSection: string,
  fromFile: string,
  loadModule: LoadModule,
): "prev" | "current" | undefined {
  const prevFn = sectionFnConstraint(prevSection, row.fn, fromFile, loadModule);
  if (!prevFn) return undefined;
  const prevParams = prevFn.params;
  const decisions: Array<"prev" | "current"> = [];
  for (const p of row.params) {
    const prevC = prevParams[p.name];
    if (!prevC) return undefined;
    const entries: ConstraintEntry[] = [
      { abs: constraintToEntryAbs(prevC, p.name), constraint: prevC },
      { abs: constraintToEntryAbs(p.constraint, p.name), constraint: p.constraint },
    ];
    const widest = widestConstraint(entries);
    if (!widest) return undefined;
    decisions.push(widest === entries[0] ? "prev" : "current");
  }
  const prevRet = prevFn.returns;
  const curRet = row.returns?.constraint;
  if (prevRet && curRet) {
    const entries: ConstraintEntry[] = [
      { abs: constraintToEntryAbs(prevRet, "__nudo_self__"), constraint: prevRet },
      { abs: constraintToEntryAbs(curRet, "__nudo_self__"), constraint: curRet },
    ];
    const widest = widestConstraint(entries);
    if (!widest) return undefined;
    decisions.push(widest === entries[0] ? "prev" : "current");
  }
  if (decisions.length === 0) return undefined;
  const first = decisions[0]!;
  return decisions.every((d) => d === first) ? first : undefined;
}

function normalizeSectionText(text: string): string {
  return text.replace(/\s*$/, "") + "\n";
}

function joinSectionTexts(base: string, sectionTexts: string[]): string {
  const normalized = sectionTexts.map(normalizeSectionText).filter((t) => t.trim() !== "");
  const tailTrimmed = base.replace(/\s+$/, "");
  if (normalized.length === 0) return tailTrimmed === "" ? "" : `${tailTrimmed}\n`;
  const trimmed = tailTrimmed.replace(/^\s+/, "");
  const lead = trimmed === "" ? "" : `${trimmed}\n\n`;
  return lead + normalized.join("\n");
}

function derivedRoundTrips(
  text: string,
  fn: string,
  fromFile: string,
  loadModule: LoadModule,
): boolean {
  const since = refineDiagCount();
  try {
    const exports = execNudoModule(text, { loadModule, fromFile });
    const v = exports[fn];
    return isNudoConstraint(v) && (v as { fn?: unknown }).fn !== undefined;
  } catch {
    return false;
  } finally {
    takeRefineDiagsSince(since);
  }
}

